CREATE SCHEMA Ecommerce_data;
CREATE TABLE Ecommerce_data.Customers AS
SELECT * FROM ecommerce.Customers WHERE 1=0;

CREATE TABLE Ecommerce_data.Orders AS
SELECT * FROM ecommerce.Orders WHERE 1=0;

CREATE TABLE Ecommerce_data.Products AS
SELECT * FROM ecommerce.Products WHERE 1=0;

CREATE TABLE Ecommerce_data.OrderItems AS
SELECT * FROM ecommerce.OrderItems WHERE 1=0;

INSERT INTO Ecommerce_data.Customers
SELECT *
FROM ecommerce.Customers
ORDER BY customer_id ASC
LIMIT 500;

INSERT INTO Ecommerce_data.Orders
SELECT *
FROM ecommerce.Orders
WHERE customer_id in (SELECT customer_id FROM Ecommerce_data.Customers);

INSERT INTO Ecommerce_data.OrderItems
SELECT *
FROM ecommerce.OrderItems
WHERE order_id IN (SELECT order_id FROM Ecommerce_data.Orders);

INSERT INTO Ecommerce_data.Products
SELECT *
FROM ecommerce.Products
WHERE product_id in (SELECT product_id FROM Ecommerce_data.OrderItems) OR product_id Like "0%";

drop database ecommerce;
